// Builds the parser bundle (mobile spec 9): the vendored Readability and Turndown, the rules from
// shared/turndown-rules.json and parser-runner.js, as one script.
//
//   node shared/vendor/build-parser-bundle.mjs           write the bundle and its constant
//   node shared/vendor/build-parser-bundle.mjs --check   exit 1 if they are stale, or a vendored file's
//                                                        sha256 differs from shared/vendor/VERSIONS.md (CI)
//
// Outputs: the APK asset kefli-parser.js inside the kefli-parser module, and ParserBundle.kt with its sha256,
// which the module checks before it runs the bundle. The extension and the fixture generator load the same
// script (kefliBundle() below). Beside it go the PDF modules (pdf.js and pdf-runner.mjs), loaded only for a PDF
// (contract 4.2, PDFs), whose sha256s ParserBundle.kt also carries for the module to check as it hands them over.

import { createHash } from 'node:crypto';
import { mkdirSync, readFileSync, writeFileSync } from 'node:fs';
import { dirname, join, relative } from 'node:path';
import { fileURLToPath } from 'node:url';

const here = dirname(fileURLToPath(import.meta.url));
const repo = join(here, '..', '..');
const sha = (s) => createHash('sha256').update(s).digest('hex');
const read = (p) => readFileSync(join(here, p), 'utf8');

const VENDORED = [
  'readability-0.6.0/Readability.js',
  'readability-0.6.0/Readability-readerable.js',
  'turndown-7.2.4/turndown.browser.umd.js',
  '../turndown-rules.json',
  'pdfjs-4.10.38/pdf.min.mjs',
  'pdfjs-4.10.38/pdf.worker.min.mjs',
];

/** The PDF modules, as the parser asks KefliHost.asset for them, and where each comes from. */
const PDF_ASSETS = [
  ['pdf.min.mjs', 'pdfjs-4.10.38/pdf.min.mjs'],
  ['pdf.worker.min.mjs', 'pdfjs-4.10.38/pdf.worker.min.mjs'],
  ['pdf-runner.mjs', 'pdf-runner.mjs'],
];

/** The bundle; the phone's adds parser-pdf.js, which loads pdf.js for a PDF. */
export function kefliBundle({ pdf = false } = {}) {
  const rules = JSON.parse(read('../turndown-rules.json'));
  // Plain concatenation at top level: Readability declares global functions and the Turndown UMD attaches to
  // `this`, which is window in a page script.
  return [
    '// Kefli parser bundle. Generated by shared/vendor/build-parser-bundle.mjs. Do not edit.',
    `window.KEFLI_RULES = ${JSON.stringify(rules)};`,
    read(VENDORED[0]),
    read(VENDORED[1]),
    read(VENDORED[2]),
    read('parser-runner.js'),
    ...(pdf ? [read('parser-pdf.js')] : []),
    'true;',
  ].join('\n;\n');
}

function vendoredMismatches() {
  const versions = read('VERSIONS.md');
  return VENDORED.filter((p) => !versions.includes(sha(readFileSync(join(here, p)))));
}

const module = join(repo, 'apps', 'mobile', 'modules', 'kefli-parser', 'android', 'src', 'main');
const bundle = kefliBundle({ pdf: true });
const pdfAssets = PDF_ASSETS.map(([name, from]) => [name, read(from)]);
const kotlinAssets = pdfAssets.map(([name, body]) => `    "${name}" to "${sha(body)}",`).join('\n');
const outputs = [
  [join(module, 'assets', 'kefli-parser.js'), bundle],
  ...pdfAssets.map(([name, body]) => [join(module, 'assets', name), body]),
  [
    join(module, 'java', 'app', 'kefli', 'parser', 'ParserBundle.kt'),
    `// Generated by shared/vendor/build-parser-bundle.mjs. Do not edit.\npackage app.kefli.parser\n\nobject ParserBundle {\n  const val ASSET = "kefli-parser.js"\n  const val SHA256 = "${sha(bundle)}"\n\n  /** The PDF modules the bundle may ask for, by name, with their sha256s. */\n  val PDF_ASSETS = mapOf(\n${kotlinAssets}\n  )\n}\n`,
  ],
];

if (process.argv[1] === fileURLToPath(import.meta.url)) {
  const check = process.argv.includes('--check');
  let bad = vendoredMismatches().map((p) => `vendored file differs from VERSIONS.md: ${p}`);
  for (const [path, body] of outputs) {
    if (check) {
      let current = '';
      try {
        current = readFileSync(path, 'utf8');
      } catch {}
      if (current !== body) bad.push(`stale: ${relative(repo, path)}`);
    } else {
      mkdirSync(dirname(path), { recursive: true });
      writeFileSync(path, body);
      console.log(`wrote ${relative(repo, path)}`);
    }
  }
  if (bad.length) {
    console.error(bad.join('\n'));
    if (check) console.error('run: node shared/vendor/build-parser-bundle.mjs');
    process.exit(1);
  }
  console.log(`parser bundle ${sha(bundle).slice(0, 16)}…, ${bundle.length} characters${check ? ', current' : ''}`);
}
